import { siteOrigin } from "../../lib/seo";

export const dynamic = "force-dynamic";

// Generated by the SEO settings (Admin → SEO)
export async function GET() {
  const origin = await siteOrigin();
  const res = await fetch(`${process.env.API_URL_INTERNAL || "http://localhost:8000"}/api/seo/sitemap.xml?base=${encodeURIComponent(origin)}`, { cache: "no-store" });
  if (!res.ok) return new Response("Not found", { status: 404 });
  return new Response(await res.text(), { headers: { "content-type": "application/xml; charset=utf-8", "cache-control": "public, max-age=300" } });
}
